// Generated by /ship coverage audit
// Value: protects=the Recents range filter keeps only articles viewed inside the chosen window, and all-time never drops one;
//   fails_when=a window length, the inclusive cutoff or unparseable-viewedAt handling changes, or "all" starts filtering;
//   why_new=range.ts had no test, and history.test.ts covers recording and parsing, not the range filter;
//   seam=none;
//   no_claim=green does not prove the range picker UI selects these ranges or that stored viewedAt values are well-formed.
import { describe, expect, test } from "bun:test";
import { filterRecentArticles } from "../../../../../../apps/mobile/src/modules/recents/lib/range";
import type { RecentArticle } from "../../../../../../apps/mobile/src/modules/recents/lib/history";

const DAY_MS = 24 * 60 * 60 * 1000;
const NOW = Date.parse("2026-08-05T12:00:00.000Z");

const viewed = (id: string, viewedAt: string): RecentArticle => ({
  feedFaviconUrl: null,
  feedSiteUrl: "https://example.com",
  feedTitle: "Example",
  feedUrl: "https://example.com/feed.xml",
  id,
  link: `https://example.com/${id}`,
  title: `Article ${id}`,
  viewedAt,
});

const viewedAgo = (id: string, ageMs: number): RecentArticle =>
  viewed(id, new Date(NOW - ageMs).toISOString());

const ids = (articles: readonly RecentArticle[]) => articles.map((article) => article.id);

describe("filterRecentArticles", () => {
  test("keeps every entry for all time, including ones whose view time cannot be parsed", () => {
    const articles = [
      viewedAgo("fresh", 0),
      viewedAgo("ancient", 400 * DAY_MS),
      viewed("garbled", "not-a-date"),
    ];

    expect(filterRecentArticles(articles, "all", NOW)).toEqual(articles);
  });

  test.each([
    { range: "today", windowDays: 1 },
    { range: "week", windowDays: 7 },
    { range: "month", windowDays: 30 },
  ] as const)(
    "$range keeps entries inside $windowDays day(s) and drops older ones",
    ({ range, windowDays }) => {
      const windowMs = windowDays * DAY_MS;
      const articles = [
        viewedAgo("just-now", 0),
        viewedAgo("inside", windowMs - 60_000),
        viewedAgo("outside", windowMs + 60_000),
        viewedAgo("ancient", 400 * DAY_MS),
      ];

      expect(ids(filterRecentArticles(articles, range, NOW))).toEqual(["just-now", "inside"]);
    },
  );

  test("widens the window from today to week to month for the same history", () => {
    const articles = [
      viewedAgo("hours", 3 * 60 * 60 * 1000),
      viewedAgo("days", 3 * DAY_MS),
      viewedAgo("weeks", 20 * DAY_MS),
      viewedAgo("months", 45 * DAY_MS),
    ];

    expect(ids(filterRecentArticles(articles, "today", NOW))).toEqual(["hours"]);
    expect(ids(filterRecentArticles(articles, "week", NOW))).toEqual(["hours", "days"]);
    expect(ids(filterRecentArticles(articles, "month", NOW))).toEqual(["hours", "days", "weeks"]);
  });

  test("includes an entry viewed exactly at the cutoff and excludes one a millisecond older", () => {
    const articles = [viewedAgo("at-cutoff", DAY_MS), viewedAgo("just-older", DAY_MS + 1)];

    expect(ids(filterRecentArticles(articles, "today", NOW))).toEqual(["at-cutoff"]);
  });

  test("drops an entry whose view time cannot be parsed from every bounded range", () => {
    const articles = [viewed("garbled", "not-a-date"), viewed("empty", ""), viewedAgo("ok", 0)];

    for (const range of ["today", "week", "month"] as const) {
      expect(ids(filterRecentArticles(articles, range, NOW))).toEqual(["ok"]);
    }
  });

  test("keeps the stored order and does not mutate the history it filters", () => {
    const articles = [
      viewedAgo("newest", 0),
      viewedAgo("older", DAY_MS / 2),
      viewedAgo("gone", 9 * DAY_MS),
    ];
    const snapshot = [...articles];

    expect(ids(filterRecentArticles(articles, "week", NOW))).toEqual(["newest", "older"]);
    expect(articles).toEqual(snapshot);
  });
});
